// Normalise the CloneX takedown payload and build the email + team alert.
const b = $input.first().json.body ?? $input.first().json;
const demo = b.mode !== "live";
const desk = b.intendedDesk || {};
const subject = (demo ? "[CLONEX DEMO] " : "") + 'Impersonation report: "' + b.threatTitle + '" impersonating ' + b.brandName + " (" + b.platform + ")";
const fallback =
  "Hello Trust & Safety team,\n\nWe represent " + b.brandName + " and are reporting " + b.threatTitle +
  (b.detectedArtifact ? " (" + b.detectedArtifact + ")" : "") + " on " + b.platform +
  ", which impersonates our brand." + (b.evidenceUrl ? "\nEvidence: " + b.evidenceUrl : "") +
  "\nRisk score: " + b.riskScore + "/100.\n\nWe ask that you review and remove it under your impersonation policy.";
let message = b.noticeText && b.noticeText.trim().length > 20 ? b.noticeText : fallback;
if (demo) message = "DEMO MODE: this notice was NOT sent to " + (desk.desk || "the platform") + ".\n\n" + message;
if (!b.to && desk.formUrl) message += "\n\nThis platform takes reports through a web form: " + desk.formUrl;
const alert = "CloneX takedown" + (demo ? " (demo)" : "") + " | " + b.brandName + ": " + b.threatTitle + " on " + b.platform +
  ", risk " + b.riskScore + "/100. " + (b.to ? "Notice emailed to " + b.to + "." : "Notice saved as a Gmail draft for review.");
return [{ json: { ok: true, mode: b.mode, to: b.to || "", subject, message, alert, platform: b.platform } }];

// SAFETY: this workflow only ever emails addresses on this list. The website is public, so without it
// anyone could make your Gmail send to any address. Add your team's addresses (lower case).
const APPROVED = [];
const p = $('Prepare notice').first().json;
const body = $('Takedown Webhook').first().json.body ?? {};
const copies = Array.isArray(body.copies) ? body.copies.map((e) => String(e).trim().toLowerCase()) : [];
const sendTo = copies.filter((e) => APPROVED.includes(e));
const blocked = copies.filter((e) => !APPROVED.includes(e));
return [{ json: { ...p, sendTo, blocked } }];
